//! The product entity of the `products` resource, generated by
//! `forge generate scaffold`. Business rules only: no HTTP, SQL or runtime
//! types, so the rules are unit-testable and shared by every adapter.

use std::fmt;

use forge::core::{Id, Version};

/// Identifier of a [`Product`]: a typed UUIDv7 generated in Rust, never by
/// the database.
pub type ProductId = Id<Product>;

/// Maximum length, in characters, of a `string` field.
pub const STRING_MAX_CHARS: usize = 255;

/// Maximum length, in characters, of a `text` field.
pub const TEXT_MAX_CHARS: usize = 65_535;

/// The values a product is made of. [`Product`] only holds values that pass
/// [`ProductAttributes::validate`].
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ProductAttributes {
    pub name: String,
    pub summary: Option<String>,
    pub price_cents: i64,
}

impl ProductAttributes {
    /// Checks every business rule and reports all violations at once.
    pub fn validate(&self) -> Result<(), ProductValidationErrors> {
        let mut errors = ProductValidationErrors::default();
        check_text(
            &mut errors,
            ProductField::Name,
            &self.name,
            STRING_MAX_CHARS,
        );
        if let Some(value) = &self.summary {
            check_text(&mut errors, ProductField::Summary, value, TEXT_MAX_CHARS);
        }
        errors.into_result()
    }
}

/// Text must not be blank and must fit `max` characters.
fn check_text(errors: &mut ProductValidationErrors, field: ProductField, value: &str, max: usize) {
    if value.trim().is_empty() {
        errors.push(field, ProductViolation::Blank);
    } else if value.chars().count() > max {
        errors.push(field, ProductViolation::TooLong { max });
    }
}

/// A product: an identity, an optimistic-locking version and valid
/// attributes.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Product {
    id: ProductId,
    version: Version,
    attributes: ProductAttributes,
}

impl Product {
    /// A new product with a fresh UUIDv7 and the initial version.
    pub fn new(attributes: ProductAttributes) -> Result<Self, ProductValidationErrors> {
        Self::restore(ProductId::new(), Version::INITIAL, attributes)
    }

    /// A product read from storage or about to replace a stored one,
    /// validated like a new one.
    pub fn restore(
        id: ProductId,
        version: Version,
        attributes: ProductAttributes,
    ) -> Result<Self, ProductValidationErrors> {
        attributes.validate()?;
        Ok(Self {
            id,
            version,
            attributes,
        })
    }

    /// The same product at `version`, after storage accepted a change.
    #[must_use]
    pub fn with_version(self, version: Version) -> Self {
        Self { version, ..self }
    }

    #[must_use]
    pub fn id(&self) -> ProductId {
        self.id
    }

    /// The optimistic-locking version: an update or delete must present it.
    #[must_use]
    pub fn version(&self) -> Version {
        self.version
    }

    #[must_use]
    pub fn attributes(&self) -> &ProductAttributes {
        &self.attributes
    }

    #[must_use]
    pub fn name(&self) -> &str {
        &self.attributes.name
    }

    #[must_use]
    pub fn summary(&self) -> Option<&str> {
        self.attributes.summary.as_deref()
    }

    #[must_use]
    pub fn price_cents(&self) -> i64 {
        self.attributes.price_cents
    }
}

/// A field of [`ProductAttributes`].
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ProductField {
    Name,
    Summary,
    PriceCents,
}

impl ProductField {
    /// The field's name in forms and storage.
    #[must_use]
    pub const fn name(self) -> &'static str {
        match self {
            Self::Name => "name",
            Self::Summary => "summary",
            Self::PriceCents => "price_cents",
        }
    }
}

/// A broken business rule.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ProductViolation {
    /// The value is empty or only whitespace.
    Blank,
    /// The value has more than `max` characters.
    TooLong { max: usize },
}

impl fmt::Display for ProductViolation {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Blank => formatter.write_str("can't be blank"),
            Self::TooLong { max } => write!(formatter, "is too long (at most {max} characters)"),
        }
    }
}

/// Every broken rule of a product, in field order.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct ProductValidationErrors {
    violations: Vec<(ProductField, ProductViolation)>,
}

impl ProductValidationErrors {
    /// Records that `field` breaks a rule.
    pub fn push(&mut self, field: ProductField, violation: ProductViolation) {
        self.violations.push((field, violation));
    }

    /// Whether no rule is broken.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.violations.is_empty()
    }

    /// The first violation of `field`.
    #[must_use]
    pub fn get(&self, field: ProductField) -> Option<ProductViolation> {
        self.violations
            .iter()
            .find(|(candidate, _)| *candidate == field)
            .map(|(_, violation)| *violation)
    }

    /// Every violation in the order it was found.
    pub fn iter(&self) -> impl Iterator<Item = (ProductField, ProductViolation)> + '_ {
        self.violations.iter().copied()
    }

    /// `Ok` when no rule is broken.
    pub fn into_result(self) -> Result<(), Self> {
        if self.is_empty() { Ok(()) } else { Err(self) }
    }
}

impl fmt::Display for ProductValidationErrors {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("product is invalid")?;
        for (index, (field, violation)) in self.violations.iter().enumerate() {
            let separator = if index == 0 { ": " } else { ", " };
            write!(formatter, "{separator}{} {violation}", field.name())?;
        }
        Ok(())
    }
}

impl std::error::Error for ProductValidationErrors {}

#[cfg(test)]
mod tests {
    use super::*;

    fn valid() -> ProductAttributes {
        ProductAttributes {
            name: "Example name".to_owned(),
            summary: Some("Example summary".to_owned()),
            price_cents: 42,
        }
    }

    #[test]
    fn new_products_get_a_uuidv7_and_the_initial_version() {
        let created = Product::new(valid());

        let Ok(entity) = created else {
            panic!("valid attributes must be accepted: {created:?}");
        };
        assert_eq!(entity.id().as_uuid().get_version_num(), 7);
        assert_eq!(entity.version(), Version::INITIAL);
        assert_eq!(entity.attributes(), &valid());
    }

    #[test]
    fn blank_and_too_long_text_is_rejected_with_every_violation() {
        let mut attributes = valid();
        attributes.name = "x".repeat(STRING_MAX_CHARS + 1);
        attributes.summary = Some(" ".to_owned());

        let Err(errors) = Product::new(attributes) else {
            panic!("blank and too long values must be rejected");
        };
        assert_eq!(
            errors.get(ProductField::Name),
            Some(ProductViolation::TooLong {
                max: STRING_MAX_CHARS
            })
        );
        assert_eq!(
            errors.get(ProductField::Summary),
            Some(ProductViolation::Blank)
        );
    }

    #[test]
    fn restore_validates_and_with_version_keeps_the_identity() -> Result<(), ProductValidationErrors>
    {
        let entity = Product::new(valid())?;
        let restored = Product::restore(entity.id(), entity.version(), valid())?;
        assert_eq!(restored, entity);

        let Ok(next) = Version::INITIAL.next() else {
            panic!("version 2 exists");
        };
        let moved = restored.with_version(next);
        assert_eq!(moved.id(), entity.id());
        assert_eq!(moved.version().get(), 2);
        Ok(())
    }
}
